script:
frappe.ui.form.on('Loan Application', {
    setup: function(frm) {
        // Override the field's depends_on expression before the form renders
        if (frm.fields_dict.repayment_periods) {
            frm.set_df_property(
                'repayment_periods',
                'depends_on',
                'eval:in_list(["Repay Over Number of Periods", "Repay Equal Principal"], doc.repayment_method)'
            );
            frm.set_df_property(
                'repayment_periods',
                'mandatory_depends_on',
                'eval:in_list(["Repay Over Number of Periods", "Repay Equal Principal"], doc.repayment_method)'
            );
        }
    },
    refresh: function(frm) {
        frm.trigger('toggle_repayment_fields');
    },
    repayment_method: function(frm) {
        frm.trigger('toggle_repayment_fields');
    },
    toggle_repayment_fields: function(frm) {
        const is_period_based = [
            'Repay Over Number of Periods',
            'Repay Equal Principal'
        ].includes(frm.doc.repayment_method);

        // Explicitly refresh field visibility
        frm.toggle_display('repayment_periods', is_period_based);
        frm.toggle_reqd('repayment_periods', is_period_based);

        if (frm.doc.repayment_method === 'Repay Fixed Amount per Period') {
            frm.toggle_display('repayment_amount', true);
            frm.toggle_reqd('repayment_amount', true);
        } else {
            frm.toggle_display('repayment_amount', false);
            frm.toggle_reqd('repayment_amount', false);
        }
    }
});

frappe.ui.form.on('Government Remittance', {

    refresh(frm) {
        frm.toggle_display('prn', frm.doc.is_mra_remittance);
    },

    is_mra_remittance(frm) {
        frm.toggle_display('prn', frm.doc.is_mra_remittance);

        // Optional: clear PRN if unticked
        if (!frm.doc.is_mra_remittance) {
            frm.set_value('prn', '');
        }
    }

});

frappe.listview_settings['Government Remittance'] = {

    onload(listview) {

        // Download MRA Remittance CSV
        listview.page.add_action_item(__('Download MRA Remittance CSV'), function () {

            let checked_items = listview.get_checked_items();

            if (!checked_items.length) {
                frappe.msgprint(__('Please select at least one Government Remittance'));
                return;
            }

            let names = checked_items.map(d => d.name);

            let url =
                '/api/method/download_mra_remittance_csv?government_remittances=' +
                encodeURIComponent(JSON.stringify(names));

            window.open(url);
        });


        // Download Normal Government Remittance CSV
        listview.page.add_action_item(__('Download Government Remittance CSV'), function () {

            let checked_items = listview.get_checked_items();

            if (!checked_items.length) {
                frappe.msgprint(__('Please select at least one Government Remittance'));
                return;
            }

            let names = checked_items.map(d => d.name);

            let url =
                '/api/method/download_government_remittance_csv?government_remittances=' +
                encodeURIComponent(JSON.stringify(names));

            window.open(url);
        });

    }

};

frappe.listview_settings['Payroll Entry'] = {

    onload(listview) {

        listview.page.add_action_item(
            __('Download Payroll as CSV'),
            function () {

                let checked_items = listview.get_checked_items();

                if (!checked_items.length) {
                    frappe.msgprint(__('Please select at least one Payroll Entry'));
                    return;
                }

                let names = checked_items.map(d => d.name);

                let url =
                    '/api/method/download_payroll_csv?payroll_entries=' +
                    encodeURIComponent(JSON.stringify(names));

                window.open(url);
            }
        );

    }
};

frappe.ui.form.on("OBDX Normal Payment Item", {

    refresh(frm) {
        set_bank_account_filter(frm);
    },

    party_type(frm) {

        // Clear fields when switching between Supplier and Employee
        frm.set_value("party_name", "");
        frm.set_value("payee_account", "");

        set_bank_account_filter(frm);
    },

    party_name(frm) {

        // Clear previously selected bank account
        frm.set_value("payee_account", "");

        set_bank_account_filter(frm);
    }

});


function set_bank_account_filter(frm) {

    frm.set_query("payee_account", function () {

        if (frm.doc.party_type && frm.doc.party_name) {

            return {
                filters: {
                    party_type: frm.doc.party_type,
                    party: frm.doc.party_name
                }
            };
        }

        return {};
    });

}

frappe.ui.form.on("OBDX Payment Batch", {

    refresh(frm) {
        set_payment_item_filter(frm);
        update_batch_totals(frm);
    },

    validate(frm) {
        update_batch_totals(frm);
    },

    payment_items_table_add(frm, cdt, cdn) {
        update_batch_totals(frm);
    },

    payment_items_table_remove(frm, cdt, cdn) {
        update_batch_totals(frm);
    }

});


frappe.ui.form.on("OBDX Normal Payment Reference", {

    amount(frm, cdt, cdn) {
        update_batch_totals(frm);
    }

});


// Filter payment items = show only submitted
function set_payment_item_filter(frm) {

    frm.set_query("payment_item", "payment_items_table", function() {

        return {
            filters: {
                docstatus: 1
            }
        };

    });

}


// update total_amount after selecting payment item
function update_batch_totals(frm) {

    let items = frm.doc.payment_items_table || [];

    let transaction_count = items.length;

    let total_amount = 0;

    items.forEach(row => {
        total_amount += flt(row.amount);
    });

    frm.set_value("num_transactions", transaction_count);
    frm.set_value("total_amount", total_amount);
}

frappe.listview_settings['OBDX Payment Batch'] = {

    onload(listview) {

        listview.page.add_action_item(
            __('Download Normal Payment CSV'),
            function () {

                let checked_items = listview.get_checked_items();

                if (!checked_items.length) {
                    frappe.msgprint(
                        __('Please select at least one OBDX Payment Batch')
                    );
                    return;
                }

                let names = checked_items.map(d => d.name);

                let url =
                    '/api/method/generate_obdx_normal_payment_csv?payment_batches=' +
                    encodeURIComponent(JSON.stringify(names));

                window.open(url);
            }
        );

    }

};

// Filter government remittance documents = show only submitted and not MRA
frappe.ui.form.on("Payroll Entry", {

    refresh(frm) {
        set_remittance_filter(frm);
    },

    custom_remittance_reference_document(frm) {

        if (!frm.doc.custom_remittance_reference_document) {
            frm.set_value("custom_trf_source_reference_number", "");
            frm.set_value("custom_funding_total_amount", 0);
            return;
        }

        frappe.db.get_value(
            "Government Remittance",
            frm.doc.custom_remittance_reference_document,
            [
                "source_ref_number",
                "payment_amount"
            ],
            function(r) {

                if (r) {

                    frm.set_value(
                        "custom_trf_source_reference_number",
                        r.source_ref_number
                    );

                    frm.set_value(
                        "custom_funding_total_amount",
                        r.payment_amount
                    );

                }

            }
        );
    }

});


function set_remittance_filter(frm) {

    frm.set_query(
        "custom_remittance_reference_document",
        function() {

            return {
                filters: {
                    docstatus: 1,
                    is_mra_remittance: 0
                }
            };

        }
    );

}

// Show button to create normal payment item against employee loan
frappe.ui.form.on("Loan Disbursement", {

    refresh(frm) {

        // Only show for submitted Loan Disbursements
        if (frm.doc.docstatus !== 1) {
            return;
        }

        // Only applicable to Employee loan disbursements
        if (frm.doc.applicant_type !== "Employee") {
            return;
        }

        frm.add_custom_button(
            __("OBDX Normal Payment Item"),
            function () {

                frappe.route_options = {
                    party_type: "Employee",
                    party_name: frm.doc.applicant,
                    amount: frm.doc.sanctioned_loan_amount,
                    loan_disbursement: frm.doc.name,
                    payment_description: "Disbursement for Loan: " + frm.doc.against_loan + " with internal reference: " + frm.doc.name
                };

                frappe.new_doc("OBDX Normal Payment Item");

            },
            __("Create")
        );

    }

});

frappe.ui.form.on("Employee", {

    refresh(frm) {
        set_salary_bank_account_filter(frm);
        set_pension_contribution_balance_filter(frm);
    }

});

function set_salary_bank_account_filter(frm) {

    frm.set_query("custom_select_bank_info", function () {

        return {
            filters: {
                party_type: "Employee",
                party: frm.doc.name
            }
        };

    });

}

function set_pension_contribution_balance_filter(frm) {

    frm.set_query("custom_pension_opening_balance", function () {

        return {
            filters: {
                employee: frm.doc.name,
                'docstatus': 1
            }
        };

    });

}

frappe.ui.form.on('Loan Application', {
    // Triggers whenever the user selects a number from the dropdown
    custom_repayment_period_months: function(frm) {
        if (frm.doc.custom_repayment_period_months) {
            // Convert the string dropdown value to an actual integer
            let integerValue = parseInt(frm.doc.custom_repayment_period_months);

            // Set the hidden core field value
            frm.set_value('repayment_periods', integerValue);
        } else {
            // Clear the core field if the dropdown is emptied
            frm.set_value('repayment_periods', null);
        }
    }
});
